import subprocess, time, shlex, sys
def start(args,w=80,h=24,name="cap"):
    subprocess.run(["tmux","kill-session","-t",name], stderr=subprocess.DEVNULL)
    cmd=" ".join(shlex.quote(a) for a in ["./executable"]+args)
    subprocess.run(["tmux","new-session","-d","-s",name,"-x",str(w),"-y",str(h),cmd])
def capture(name="cap",esc=False):
    cmd=["tmux","capture-pane","-t",name,"-p"]
    if esc: cmd.append("-e")
    return subprocess.run(cmd,capture_output=True,text=True).stdout
def kill(name="cap"): subprocess.run(["tmux","kill-session","-t",name], stderr=subprocess.DEVNULL)
def show(args,w=80,h=24,wait=0.6):
    start(args,w,h); time.sleep(wait)
    out=capture()
    lines=out.split("\n")
    for i,l in enumerate(lines):
        print(f"{i:02d}|{l}| len={len(l)}")
    print("ESC:")
    oute=capture(esc=True)
    for i,l in enumerate(oute.split("\n")):
        print(f"{i:02d}|{l!r}")
    kill()
if __name__=="__main__":
    import json
    args=json.loads(sys.argv[1]) if len(sys.argv)>1 else []
    w=int(sys.argv[2]) if len(sys.argv)>2 else 80
    h=int(sys.argv[3]) if len(sys.argv)>3 else 24
    show(args,w,h)
