{"command":"python3 - <<'PY'
import os, subprocess, pty, time, select, fcntl, termios, struct
def read_master(master, dur=0.3):
    out=b""; end=time.time()+dur
    while time.time()<end:
        r,_,_=select.select([master],[],[],0.1)
        if r:
            try: chunk=os.read(master,65536)
            except: break
            if not chunk: break
            out+=chunk
    return out

def test(mode):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH",24,80,0,0))
    slave_name=os.ttyname(slave)
    env=dict(os.environ); env["TERM"]="xterm"
    if mode=="normal":
        p=subprocess.Popen(["./executable"], stdout=slave, stderr=slave, env=env, stdin=slave)
    else:
        p=subprocess.Popen(["./executable","-T",slave_name], stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env, stdin=subprocess.PIPE)
    time.sleep(0.5); initial=read_master(master,0.2)
    print(mode,"initial len",len(initial),"poll",p.poll())
    os.write(master,b"q")
    for i in range(6):
        time.sleep(0.5); dat=read_master(master,0.05); print(mode, "after q",i, p.poll(), "extra len", len(dat), dat[:100])
        if p.poll() is not None: break
    if p.poll() is None: p.kill()
    print(mode,"final",p.wait())
test("normal")
test("T")
