import os, subprocess, pty, time, select, fcntl, termios, struct
def spawn(args):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH",24,80,0,0))
    env=dict(os.environ); env["TERM"]="xterm"
    p=subprocess.Popen(["./executable"]+args, stdout=slave, stderr=slave, env=env, stdin=slave, close_fds=True)
    os.close(slave); return p, master
def read_avail(m, dur):
    out=b""; end=time.time()+dur
    while time.time()<end:
        r,_,_=select.select([m],[],[],0.02)
        if r:
            try: d=os.read(m,65536)
            except: break
            if d: out+=d
    return out
def test(args,key,wait):
    p,m=spawn(args); time.sleep(wait); read_avail(m,0.05)
    t0=time.time(); os.write(m,key); out=read_avail(m,2.5); el=None
    # find when first output arrives: we need timed reading instead
    print(args,key,wait,"output len in 2.5s after",len(out),"poll",p.poll())
    if p.poll() is None: p.kill(); p.wait()
    os.close(m)
