def spawn(args):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH",24,80,0,0))
    env=dict(os.environ); env["TERM"]="xterm"
    p=subprocess.Popen(["./executable"]+args, stdout=slave, stderr=slave, env=env, stdin=slave, close_fds=True)
    os.close(slave); return p, master
def read_avail(m, dur):
    out=b""; end=time.time()+dur
    while time.time()<end:
        r,_,_=select.select([m],[],[],0.02)
        if r:
            try: d=os.read(m,65536)
            except: break
            if d: out+=d
    return out
