    master, slave = pty.openpty(); fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH",24,80,0,0))
    env=dict(os.environ); env["TERM"]=term
    p=subprocess.Popen(["./executable"]+args, stdout=slave, stderr=slave, env=env, stdin=slave); os.close(slave)
    time.sleep(0.5); out=b""
    while True:
        r,_,_=select.select([master],[],[],0.1)
