        out+=d
    print(term,args,"poll",p.poll(),"out",out[:600])
    if p.poll() is None:
        os.write(master,b"q"); time.sleep(0.3)
    if p.poll() is None: p.kill()
    print(" rc",p.wait()); os.close(master)
for t in ["dumb","vt100","xterm-mono","unknown","ansi"]:
    run(t)
