#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>
#include <unistd.h>

typedef struct {
        bool second;
        bool screensaver;
        bool box;
        bool center;
        bool bold;
        bool twelve;
        bool utc;
        bool rebound;
        bool noquit;
        bool showdate;
        bool blink;
} Options;

static struct {
        Options option;
        int color;
        const char *date_format;
        long delay_sec;
        long nsdelay;
        FILE *ttyfp;
        SCREEN *ttyscr;
        WINDOW *framewin;
        WINDOW *datewin;
        int x;
        int y;
        int dx;
        int dy;
        int width;
        int date_width;
        bool date_on_top;
} ttyclock;

static void build_date(char *out, size_t size, const struct tm *tmv);
static void move_windows(void);

static void init(void)
{
        if (ttyclock.ttyfp) {
                ttyclock.ttyscr = newterm(NULL, ttyclock.ttyfp, ttyclock.ttyfp);
                assert(ttyclock.ttyscr != NULL);
                set_term(ttyclock.ttyscr);
        } else {
                initscr();
        }
        noecho();
        cbreak();
        curs_set(0);
        start_color();
        use_default_colors();
        init_pair(1, -1, ttyclock.color);
        init_pair(2, ttyclock.color, -1);
        ttyclock.width = ttyclock.option.second ? 54 : 35;
        ttyclock.framewin = newwin(7, ttyclock.width, 0, 0);
        if (ttyclock.framewin)
                keypad(ttyclock.framewin, TRUE);
        {
                char date[8192];
                time_t now = time(NULL);
                struct tm tmv;
                if (ttyclock.option.utc)
                        gmtime_r(&now, &tmv);
                else
                        localtime_r(&now, &tmv);
                build_date(date, sizeof(date), &tmv);
                ttyclock.date_width = (int)strlen(date) + 2;
        }
        ttyclock.datewin = newwin(3, ttyclock.date_width, 6,
                                  ttyclock.width / 2 - ttyclock.date_width / 2);
        if (ttyclock.option.center) {
                ttyclock.x = COLS / 2 - ttyclock.width / 2;
                ttyclock.y = LINES / 2 - 3;
                move_windows();
        }
}

static void move_windows(void)
{
        if (ttyclock.framewin)
                mvwin(ttyclock.framewin, ttyclock.y, ttyclock.x);
        if (ttyclock.datewin)
                mvwin(ttyclock.datewin, ttyclock.y + 6,
                      ttyclock.x + ttyclock.width / 2 - ttyclock.date_width / 2);
        ttyclock.date_on_top = true;
}

static void get_tm(struct tm *tmv)
{
        time_t now = time(NULL);
        if (ttyclock.option.utc)
                gmtime_r(&now, tmv);
        else
                localtime_r(&now, tmv);
}

static void build_date(char *out, size_t size, const struct tm *tmv)
{
        char formatted[8192];
        formatted[0] = '\0';
        strftime(formatted, sizeof(formatted), ttyclock.date_format, tmv);
        if (ttyclock.option.twelve)
                snprintf(out, size, "%s [%s]", formatted,
                         tmv->tm_hour >= 12 ? "PM" : "AM");
        else
                snprintf(out, size, "%s", formatted);
}

static const unsigned char digit_bits[10][5] = {
        {7, 5, 5, 5, 7},
        {1, 1, 1, 1, 1},
        {7, 1, 7, 4, 7},
        {7, 4, 7, 1, 7},
        {5, 5, 7, 1, 1},
        {7, 4, 7, 1, 7},
        {7, 4, 7, 5, 7},
        {7, 1, 1, 1, 1},
        {7, 5, 7, 5, 7},
        {7, 5, 7, 1, 7}
};

static void draw_number(int n, int x)
{
        int r, c;
        attr_t attr = COLOR_PAIR(1) | (ttyclock.option.bold ? A_BLINK : 0);
        for (r = 0; r < 5; ++r) {
                for (c = 0; c < 3; ++c) {
                        if (digit_bits[n][r] & (4 >> c)) {
                                wattron(ttyclock.framewin, attr);
                                mvwaddstr(ttyclock.framewin, 1 + r, x + 2 * c, "  ");
                                wattroff(ttyclock.framewin, attr);
                        }
                }
        }
}

static void draw_colon(int x, bool show)
{
        attr_t attr = COLOR_PAIR(1) | (ttyclock.option.bold ? A_BLINK : 0);
        if (!show)
                return;
        wattron(ttyclock.framewin, attr);
        mvwaddstr(ttyclock.framewin, 2, x + 2, "  ");
        mvwaddstr(ttyclock.framewin, 4, x + 2, "  ");
        wattroff(ttyclock.framewin, attr);
}

static void step_rebound(void)
{
        int max_x = COLS - ttyclock.width;
        int max_y = LINES - 9;
        if (max_x > 0) {
                ttyclock.x += ttyclock.dx;
                if (ttyclock.x >= max_x) {
                        ttyclock.x = max_x;
                        ttyclock.dx = -1;
                } else if (ttyclock.x <= 0) {
                        ttyclock.x = 0;
                        ttyclock.dy = ttyclock.dy;
                        ttyclock.dx = 1;
                }
        }
        if (max_y > 0) {
                ttyclock.y += ttyclock.dy;
                if (ttyclock.y >= max_y) {
                        ttyclock.y = max_y;
                        ttyclock.dy = -1;
                } else if (ttyclock.y <= 0) {
                        ttyclock.y = 0;
                        ttyclock.dy = 1;
                }
        }
        move_windows();
}

static void draw_clock(void)
{
        struct tm tmv;
        char date[16384];
        int hour;
        bool colon_show;

        get_tm(&tmv);
        build_date(date, sizeof(date), &tmv);
        if ((int)strlen(date) + 2 != ttyclock.date_width) {
                ttyclock.date_width = (int)strlen(date) + 2;
                if (ttyclock.datewin) {
                        wresize(ttyclock.datewin, 3, ttyclock.date_width);
                        mvwin(ttyclock.datewin, ttyclock.y + 6,
                              ttyclock.x + ttyclock.width / 2 - ttyclock.date_width / 2);
                }
                ttyclock.date_on_top = true;
        }
        if (ttyclock.option.rebound && !ttyclock.option.center)
                step_rebound();

        hour = tmv.tm_hour;
        if (ttyclock.option.twelve) {
                hour %= 12;
                if (hour == 0)
                        hour = 12;
        }
        colon_show = !ttyclock.option.blink || (tmv.tm_sec % 2 != 0);

        init_pair(1, -1, ttyclock.color);
        init_pair(2, ttyclock.color, -1);

        erase();

        werase(ttyclock.framewin);
        wattrset(ttyclock.framewin, A_NORMAL);
        if (ttyclock.option.box)
                box(ttyclock.framewin, 0, 0);
        draw_number(hour / 10, 1);
        draw_number(hour % 10, 8);
        draw_colon(14, colon_show);
        draw_number(tmv.tm_min / 10, 20);
        draw_number(tmv.tm_min % 10, 27);
        if (ttyclock.option.second) {
                draw_colon(33, colon_show);
                draw_number(tmv.tm_sec / 10, 39);
                draw_number(tmv.tm_sec % 10, 46);
        }

        if (ttyclock.option.showdate && ttyclock.datewin) {
                attr_t attr = COLOR_PAIR(2) | (ttyclock.option.bold ? A_BOLD : 0);
                werase(ttyclock.datewin);
                wattrset(ttyclock.datewin, A_NORMAL);
                if (ttyclock.option.box)
                        box(ttyclock.datewin, 0, 0);
                wattron(ttyclock.datewin, attr);
                mvwaddstr(ttyclock.datewin, 1, 1, date);
                wattroff(ttyclock.datewin, attr);
        }

        wnoutrefresh(stdscr);
        if (ttyclock.date_on_top) {
                wnoutrefresh(ttyclock.framewin);
                if (ttyclock.option.showdate && ttyclock.datewin)
                        wnoutrefresh(ttyclock.datewin);
        } else {
                if (ttyclock.option.showdate && ttyclock.datewin)
                        wnoutrefresh(ttyclock.datewin);
                wnoutrefresh(ttyclock.framewin);
        }
        doupdate();
}

static bool handle_resize(void)
{
        if (ttyclock.option.center) {
                ttyclock.x = COLS / 2 - ttyclock.width / 2;
                ttyclock.y = LINES / 2 - 3;
                move_windows();
                return true;
        }
        ttyclock.date_on_top = false;
        return false;
}

