        }

        switch (k) {
        case 'q':
                return !ttyclock.option.noquit;
        case 'h':
        case KEY_LEFT:
                if (!ttyclock.option.center && ttyclock.x > 0) {
                        ttyclock.x--;
                        move_windows();
                }
                break;
        case 'l':
        case KEY_RIGHT:
                if (!ttyclock.option.center && ttyclock.x < COLS - ttyclock.width) {
                        ttyclock.x++;
                        move_windows();
                }
                break;
        case 'k':
        case KEY_UP:
                if (!ttyclock.option.center && ttyclock.y > 0) {
                        ttyclock.y--;
                        move_windows();
                }
                break;
        case 'j':
        case KEY_DOWN:
                if (!ttyclock.option.center && ttyclock.y < LINES - 9) {
                        ttyclock.y++;
                        move_windows();
                }
                break;
