                ttyclock.date_width = (int)strlen(date) + 2;
        }
        ttyclock.datewin = newwin(3, ttyclock.date_width, 6,
                                  ttyclock.width / 2 - ttyclock.date_width / 2);
        if (ttyclock.option.center) {
                ttyclock.x = COLS / 2 - ttyclock.width / 2;
                ttyclock.y = LINES / 2 - 3;
                move_windows();
        }
}

static void move_windows(void)
{
        if (ttyclock.framewin)
                mvwin(ttyclock.framewin, ttyclock.y, ttyclock.x);
        if (ttyclock.datewin)
                mvwin(ttyclock.datewin, ttyclock.y + 6,
                      ttyclock.x + ttyclock.width / 2 - ttyclock.date_width / 2);
        ttyclock.date_on_top = true;
}

static void get_tm(struct tm *tmv)
{
        time_t now = time(NULL);
        if (ttyclock.option.utc)
                gmtime_r(&now, tmv);
        else
                localtime_r(&now, tmv);
}

static void build_date(char *out, size_t size, const struct tm *tmv)
{
        char formatted[8192];
        formatted[0] = '\0';
        strftime(formatted, sizeof(formatted), ttyclock.date_format, tmv);
        if (ttyclock.option.twelve)
                snprintf(out, size, "%s [%s]", formatted,
                         tmv->tm_hour >= 12 ? "PM" : "AM");
        else
                snprintf(out, size, "%s", formatted);
}

static const unsigned char digit_bits[10][5] = {
        {7, 5, 5, 5, 7},
        {1, 1, 1, 1, 1},
        {7, 1, 7, 4, 7},
        {7, 4, 7, 1, 7},
        {5, 5, 7, 1, 1},
        {7, 4, 7, 1, 7},
        {7, 4, 7, 5, 7},
        {7, 1, 1, 1, 1},
        {7, 5, 7, 5, 7},
        {7, 5, 7, 1, 7}
};

static void draw_number(int n, int x)
{
        int r, c;
        attr_t attr = COLOR_PAIR(1) | (ttyclock.option.bold ? A_BLINK : 0);
        for (r = 0; r < 5; ++r) {
                for (c = 0; c < 3; ++c) {
                        if (digit_bits[n][r] & (4 >> c)) {
                                wattron(ttyclock.framewin, attr);
                                mvwaddstr(ttyclock.framewin, 1 + r, x + 2 * c, "  ");
                                wattroff(ttyclock.framewin, attr);
                        }
                }
        }
}

static void draw_colon(int x, bool show)
{
        attr_t attr = COLOR_PAIR(1) | (ttyclock.option.bold ? A_BLINK : 0);
        if (!show)
                return;
        wattron(ttyclock.framewin, attr);
        mvwaddstr(ttyclock.framewin, 2, x + 2, "  ");
        mvwaddstr(ttyclock.framewin, 4, x + 2, "  ");
        wattroff(ttyclock.framewin, attr);
}

static void step_rebound(void)
{
        int max_x = COLS - ttyclock.width;
        int max_y = LINES - 9;
        if (max_x > 0) {
                ttyclock.x += ttyclock.dx;
                if (ttyclock.x >= max_x) {
                        ttyclock.x = max_x;
                        ttyclock.dx = -1;
                } else if (ttyclock.x <= 0) {
                        ttyclock.x = 0;
                        ttyclock.dy = ttyclock.dy;
                        ttyclock.dx = 1;
                }
        }
        if (max_y > 0) {
                ttyclock.y += ttyclock.dy;
                if (ttyclock.y >= max_y) {
                        ttyclock.y = max_y;
                        ttyclock.dy = -1;
                } else if (ttyclock.y <= 0) {
                        ttyclock.y = 0;
                        ttyclock.dy = 1;
                }
        }
        move_windows();
}

static void draw_clock(void)
{
        struct tm tmv;
        char date[16384];
        int hour;
        bool colon_show;

        get_tm(&tmv);
        build_date(date, sizeof(date), &tmv);
        if ((int)strlen(date) + 2 != ttyclock.date_width) {
                ttyclock.date_width = (int)strlen(date) + 2;
                if (ttyclock.datewin) {
                        wresize(ttyclock.datewin, 3, ttyclock.date_width);
                        mvwin(ttyclock.datewin, ttyclock.y + 6,
                              ttyclock.x + ttyclock.width / 2 - ttyclock.date_width / 2);
                }
                ttyclock.date_on_top = true;
        }
        if (ttyclock.option.rebound && !ttyclock.option.center)
                step_rebound();

        hour = tmv.tm_hour;
        if (ttyclock.option.twelve) {
                hour %= 12;
                if (hour == 0)
                        hour = 12;
        }
        colon_show = !ttyclock.option.blink || (tmv.tm_sec % 2 != 0);

        init_pair(1, -1, ttyclock.color);
        init_pair(2, ttyclock.color, -1);

        erase();

        werase(ttyclock.framewin);
        wattrset(ttyclock.framewin, A_NORMAL);
        if (ttyclock.option.box)
                box(ttyclock.framewin, 0, 0);
        draw_number(hour / 10, 1);
        draw_number(hour % 10, 8);
        draw_colon(14, colon_show);
        draw_number(tmv.tm_min / 10, 20);
        draw_number(tmv.tm_min % 10, 27);
        if (ttyclock.option.second) {
                draw_colon(33, colon_show);
                draw_number(tmv.tm_sec / 10, 39);
                draw_number(tmv.tm_sec % 10, 46);
        }

        if (ttyclock.option.showdate && ttyclock.datewin) {
                attr_t attr = COLOR_PAIR(2) | (ttyclock.option.bold ? A_BOLD : 0);
                werase(ttyclock.datewin);
                wattrset(ttyclock.datewin, A_NORMAL);
                if (ttyclock.option.box)
                        box(ttyclock.datewin, 0, 0);
                wattron(ttyclock.datewin, attr);
                mvwaddstr(ttyclock.datewin, 1, 1, date);
                wattroff(ttyclock.datewin, attr);
        }

        wnoutrefresh(stdscr);
        if (ttyclock.date_on_top) {
                wnoutrefresh(ttyclock.framewin);
                if (ttyclock.option.showdate && ttyclock.datewin)
                        wnoutrefresh(ttyclock.datewin);
        } else {
                if (ttyclock.option.showdate && ttyclock.datewin)
                        wnoutrefresh(ttyclock.datewin);
                wnoutrefresh(ttyclock.framewin);
        }
        doupdate();
}

static bool handle_resize(void)
{
        if (ttyclock.option.center) {
                ttyclock.x = COLS / 2 - ttyclock.width / 2;
                ttyclock.y = LINES / 2 - 3;
                move_windows();
                return true;
        }
        ttyclock.date_on_top = false;
        return false;
}

/* Returns true when the program should quit. */
static bool handle_key(int key)
{
        int k = key;

        if (k == KEY_RESIZE) {
                handle_resize();
                return false;
        }
        if (k >= 0 && k < 256)
                k = tolower(k);

        if (k >= '0' && k <= '7') {
                ttyclock.color = k - '0';
                return false;
        }

        switch (k) {
        case 'q':
                return !ttyclock.option.noquit;
        case 'h':
        case KEY_LEFT:
                if (!ttyclock.option.center && ttyclock.x > 0) {
                        ttyclock.x--;
                        move_windows();
                }
                break;
        case 'l':
        case KEY_RIGHT:
                if (!ttyclock.option.center && ttyclock.x < COLS - ttyclock.width) {
                        ttyclock.x++;
                        move_windows();
                }
                break;
        case 'k':
        case KEY_UP:
                if (!ttyclock.option.center && ttyclock.y > 0) {
                        ttyclock.y--;
                        move_windows();
                }
                break;
        case 'j':
        case KEY_DOWN:
                if (!ttyclock.option.center && ttyclock.y < LINES - 9) {
                        ttyclock.y++;
                        move_windows();
                }
                break;
        case 'c':
                ttyclock.option.center = !ttyclock.option.center;
                if (ttyclock.option.center) {
                        ttyclock.x = COLS / 2 - ttyclock.width / 2;
                        ttyclock.y = LINES / 2 - 3;
                }
                move_windows();
                break;
        case 'r':
                ttyclock.option.rebound = !ttyclock.option.rebound;
                break;
        case 's':
                ttyclock.option.second = !ttyclock.option.second;
                ttyclock.width = ttyclock.option.second ? 54 : 35;
                if (ttyclock.framewin)
                        wresize(ttyclock.framewin, 7, ttyclock.width);
                if (ttyclock.option.center) {
                        ttyclock.x = COLS / 2 - ttyclock.width / 2;
                        ttyclock.y = LINES / 2 - 3;
                } else if (ttyclock.x + ttyclock.width >= COLS) {
                        ttyclock.x = COLS - ttyclock.width - 1;
                }
                move_windows();
                break;
        case 't':
                ttyclock.option.twelve = !ttyclock.option.twelve;
                break;
        case 'b':
                ttyclock.option.bold = !ttyclock.option.bold;
                break;
        case 'x':
                ttyclock.option.box = !ttyclock.option.box;
                ttyclock.date_on_top = false;
                break;
        default:
                break;
        }
        return false;
}

static bool screensaver_check(void)
{
        struct timespec ts;
        int key;

        ts.tv_sec = ttyclock.delay_sec;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
        ts.tv_sec = 0;
        ts.tv_nsec = ttyclock.nsdelay;
        nanosleep(&ts, NULL);

        if (!ttyclock.framewin)
                return false;
        wtimeout(ttyclock.framewin, 0);
        key = wgetch(ttyclock.framewin);
        if (key == ERR)
                return false;
        if (key == KEY_RESIZE && ttyclock.option.noquit) {
                /* A resize is consumed like any other key in this mode. */
                return false;
        }
        return !ttyclock.option.noquit;
}

static void print_usage(void)
{
        printf("usage : tty-clock [-iuvsScbtrahDBxn] [-C [0-7]] [-f format] [-d delay] [-a nsdelay] [-T tty] \n");
        printf("    -s            Show seconds                                   \n");
        printf("    -S            Screensaver mode                               \n");
        printf("    -x            Show box                                       \n");
        printf("    -c            Set the clock at the center of the terminal    \n");
        printf("    -C [0-7]      Set the clock color                            \n");
        printf("    -b            Use bold colors                                \n");
        printf("    -t            Set the hour in 12h format                     \n");
        printf("    -u            Use UTC time                                   \n");
        printf("    -T tty        Display the clock on the specified terminal    \n");
        printf("    -r            Do rebound the clock                           \n");
        printf("    -f format     Set the date format                            \n");
        printf("    -n            Don't quit on keypress                         \n");
        printf("    -v            Show tty-clock version                         \n");
        printf("    -i            Show some info about tty-clock                 \n");
        printf("    -h            Show this page                                 \n");
        printf("    -D            Hide date                                      \n");
        printf("    -B            Enable blinking colon                          \n");
        printf("    -d delay      Set the delay between two redraws of the clock. Default 1s. \n");
        printf("    -a nsdelay    Additional delay between two redraws in nanoseconds. Default 0ns.\n");
}

int main(int argc, char **argv)
{
        int opt;

        ttyclock.color = 2;
        ttyclock.date_format = "%Y-%m-%d";
        ttyclock.delay_sec = 1;
        ttyclock.nsdelay = 0;
        ttyclock.dx = 1;
        ttyclock.dy = 1;
        ttyclock.option.showdate = true;

        while ((opt = getopt(argc, argv, "iuvsScbtrahDBxnC:f:d:a:T:")) != -1) {
                switch (opt) {
                case 'i':
                        printf("TTY-Clock 2 \xc2\xa9 by Martin Duquesnoy (xorg62@gmail.com), Grey (grey@greytheory.net)\n");
                        exit(EXIT_SUCCESS);
                case 'v':
                        printf("TTY-Clock 2 \xc2\xa9 devel version\n");
                        exit(EXIT_SUCCESS);
                case 'h':
                        print_usage();
                        exit(EXIT_SUCCESS);
                case 'u':
                        ttyclock.option.utc = true;
                        break;
                case 's':
                        ttyclock.option.second = true;
                        break;
                case 'S':
                        ttyclock.option.screensaver = true;
                        break;
                case 'c':
                        ttyclock.option.center = true;
                        break;
                case 'b':
                        ttyclock.option.bold = true;
                        break;
                case 't':
                        ttyclock.option.twelve = true;
                        break;
                case 'r':
                        ttyclock.option.rebound = true;
                        break;
                case 'n':
                        ttyclock.option.noquit = true;
                        break;
                case 'D':
                        ttyclock.option.showdate = false;
                        break;
                case 'B':
                        ttyclock.option.blink = true;
                        break;
                case 'x':
                        ttyclock.option.box = true;
                        break;
                case 'C': {
                        int c = atoi(optarg);
                        if (c >= 0 && c <= 7)
                                ttyclock.color = c;
                        break;
                }
                case 'f':
                        ttyclock.date_format = optarg;
                        break;
                case 'd': {
                        long d = atol(optarg);
                        if (d >= 0)
                                ttyclock.delay_sec = d;
                        break;
                }
                case 'a': {
                        long a = atol(optarg);
                        if (a >= 0)
                                ttyclock.nsdelay = a;
                        break;
                }
                case 'T': {
                        struct stat st;
                        FILE *fp;
                        if (stat(optarg, &st) == -1) {
                                fprintf(stderr, "tty-clock: error: couldn't stat '%s': %s.\n",
                                        optarg, strerror(errno));
                                exit(EXIT_FAILURE);
                        }
                        if (!S_ISCHR(st.st_mode)) {
                                fprintf(stderr, "tty-clock: error: '%s' doesn't appear to be a character device.\n",
                                        optarg);
                                exit(EXIT_FAILURE);
                        }
                        fp = fopen(optarg, "r+");
                        if (!fp) {
                                fprintf(stderr, "tty-clock: error: '%s' couldn't be opened: %s.\n",
                                        optarg, strerror(errno));
                                exit(EXIT_FAILURE);
                        }
                        ttyclock.ttyfp = fp;
                        break;
                }
                case '?':
                default:
                        print_usage();
                        exit(EXIT_SUCCESS);
                }
        }

        init();

        for (;;) {
                int key;
                long ms;

                draw_clock();

                if (ttyclock.option.screensaver) {
                        if (screensaver_check())
                                break;
                        continue;
                }

                ms = ttyclock.delay_sec * 1000;
                if (ttyclock.nsdelay < 1000000000L)
                        ms += ttyclock.nsdelay / 1000000L;
                if (ms > 2147483647L)
                        ms = 2147483647L;
                wtimeout(ttyclock.framewin, (int)ms);
                key = wgetch(ttyclock.framewin);
                if (key == ERR)
                        continue;
                if (handle_key(key))
                        break;
        }

        endwin();
        return EXIT_SUCCESS;
}
